"""Random 32-bit values for the bit counter.

Values are assembled out of chosen bit positions rather than picked and then
examined, which is what lets each case say honestly how it was built.
"""


def generate(rng, count):
    builders = (_anything, _one_bit, _low_run, _high_bits)
    return [builders[i % len(builders)](rng, i + 1) for i in range(count)]


def _case(name, value, description=""):
    return {"name": name, "stdin": "%d\n" % value, "description": description}


def _anything(rng, index):
    return _case("a random value #%d" % index, rng.randrange(0, 2 ** 32))


def _one_bit(rng, index):
    bit = rng.randrange(32)
    return _case("bit %d alone #%d" % (bit, index), 1 << bit,
                 "A power of two: one bit set, the rest clear.")


def _low_run(rng, index):
    width = rng.randint(2, 24)
    return _case("the bottom %d bits #%d" % (width, index), (1 << width) - 1,
                 "A solid run of set bits starting at bit 0.")


def _high_bits(rng, index):
    value = 0
    for bit in rng.sample(range(16, 32), rng.randint(2, 6)):
        value |= 1 << bit
    return _case("scattered high bits #%d" % index, value,
                 "Everything set is at bit 16 or above, including sometimes "
                 "bit 31.")
